import{_ as t,l as r,o as e,c as d,v as n,p as s,x as o,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"并查集","description":"","frontmatter":{"title":"并查集","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/union-find.md","filePath":"cs/union-find.md","lastUpdated":1789023840000}'),h={name:"cs/union-find.md"};function f(u,a,m,_,A,T){const i=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=n('<h1 id="并查集" tabindex="-1">并查集 <a class="header-anchor" href="#并查集" aria-label="Permalink to &quot;并查集&quot;">​</a></h1><div class="epigraph"><p>元素分在若干不相交集合里，只问是否同类、以及把两类合并；路径压缩加按秩合并以后，摊还几乎是常数。</p><footer>—— 据 Tarjan, Efficiency of a Good But Not Linear Set Union Algorithm, JACM 1975；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/radix-tree">上一课</a>按键的符号结构存放。<a href="/cs/adt-cost">抽象数据类型</a>允许合同里没有「按值查找」。<a href="/cs/amortized-analysis">摊还分析</a>已经准备好势能语言。<a href="/cs/graph-definition">图的定义</a>里连通分量是分区。本课不重讲前缀。缺口是分区 ADT：<code>find</code> 与 <code>union</code>，表示用父指针森林，分析用摊还，不是期望散列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>维护 \\(\\{1,\\ldots,n\\}\\) 的划分。查询 \\(a,b\\) 是否同一块，或把两块合成一块。用 BST 集合存每块，union 要搬元素。缺口是：<strong>每元素一个父指针，根为代表；union 只改根；find 沿父走到根</strong>。朴素则树可变链，\\(\\Theta(n)\\)。按秩（或按大小）合并限制高度；路径压缩把沿途点直接挂到根。</p><p>Tarjan 证明压缩+按秩的摊还是反 Ackermann \\(\\alpha(n)\\)，实际等于常数。本课不把 \\(\\alpha\\) 的定义展开成数论，只钉「比 \\(\\log\\) 还扁的摊还」。</p><p><span class="marginnote">并查集不给出块内元素列表（除非另存）。合同极窄，所以才能极快。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>MakeSet(x)</code>：父为自己，秩 0。<code>Find(x)</code>：递归或两趟压缩。<code>Union(x,y)</code>：比两根的秩，矮挂高，相等则升一方之秩。</p>',9)),(e(),s(p,null,{default:o(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%83%E7%B4%A0%22%5D%20--%3E%20P%5B%22%E7%88%B6%E6%8C%87%E9%92%88%22%5D%0A%20%20P%20--%3E%20ROOT%5B%22%E6%A0%B9%20%3D%20%E4%BB%A3%E8%A1%A8%22%5D%0A%20%20ROOT%20--%3E%20U%5B%22union%20%E5%8F%AA%E9%93%BE%E6%8E%A5%E6%A0%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>与链表表示的「按大小合并」同类：总是把小块挂到大块，无压缩时高度 \\(O(\\log n)\\)。压缩再把已经走过的路摊掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Kruskal 最小生成树把边按权加入、用并查集检测是否成环——算法课再用，本课只交结构。动态连通性若还要删边，并查集不够，合同不含 split。<code>find</code> 的返回值只作代表，代表编号可以随 union 改变，调用方不得缓存过期根。</p><p>表示是数组 <code>parent[i]</code>，局部性好于树节点堆分配。秩数组并行。这是<a href="/cs/array-random-access">数组与随机访问</a>作为内部表示，对外仍是分区 ADT。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入可持久化并查集、不处理并查集上的删除。也不把 \\(\\alpha(n)\\) 写成 \\(O(1)\\) 最坏——最坏单次仍可较长，摊还小。</p><p>后课默认：不相交集合查询用并查集。图要存边而不只是分量时，需要邻接表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分区 ADT：find / union；森林 + 压缩 + 按秩，摊还几乎常数。</li><li>不支持列成员、不支持删边。</li><li>图的边集怎么放，下一课邻接表与矩阵。</li><li>代表编号可随 union 改变；调用方不得缓存过期根。</li><li>出处：Tarjan, <em>JACM</em>, 1975；Cormen et al. 第 21 章。</li></ul>',9))])}const B=t(h,[["render",f]]);export{x as __pageData,B as default};
